async function loadDsqlSchema(){if(!$('cluster-select').value)return;dsqlLoaded=true;$('dsql-tables').innerHTML='<div class="empty">Connecting to the cluster…</div>';try{const schema=await post('/api/dsql/schema',{clusterName:$('cluster-select').value});dsqlTables=schema.tables||[];erdRelationships=schema.relationships||[];erdPositions.clear();$('dsql-strip').innerHTML=`<b>${esc(schema.identifier)}</b><span class="schema-chip">${esc(schema.host)}</span><span class="schema-chip">${esc(schema.user)}@${esc(schema.database)}</span><span>${dsqlTables.length} tables · ${esc(shortVersion(schema.version))}</span>`;renderDsqlTables();updateErdTabCount();renderErd()}catch(e){dsqlLoaded=false;dsqlTables=[];erdRelationships=[];updateErdTabCount();renderErd();toast(e.message);$('dsql-strip').textContent=e.message;$('dsql-tables').innerHTML=`<div class="preview-error">${esc(e.message)}</div>`}}
function getSqlContext(){const text=$('dsql-sql').value,cursor=$('dsql-sql').selectionStart,beforeCursor=text.slice(0,cursor).toUpperCase();let inSelectList=false,inFrom=false,inWhere=false,inOn=false,inJoin=false;const selectMatch=beforeCursor.match(/SELECT\b/),fromMatch=beforeCursor.match(/\bFROM\b/),whereMatch=beforeCursor.match(/\bWHERE\b/),onMatch=beforeCursor.match(/\bON\b/),joinMatch=beforeCursor.match(/\b(INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|CROSS\s+JOIN|JOIN)\b/);let lastKw=null;if(selectMatch){if(!fromMatch||selectMatch.index>fromMatch.index)lastKw='SELECT',inSelectList=true;else if(fromMatch&&(!whereMatch||fromMatch.index>whereMatch.index))lastKw='FROM',inFrom=true}if(whereMatch&&(!fromMatch||whereMatch.index>fromMatch.index)&&(!onMatch||whereMatch.index>onMatch.index))lastKw='WHERE',inWhere=true;if(onMatch&&(!whereMatch||onMatch.index>whereMatch.index))lastKw='ON',inOn=true;if(joinMatch)inJoin=true;return {lastKw,inSelectList,inFrom,inWhere,inOn,inJoin}}
function extractTableNames(){const text=$('dsql-sql').value.toUpperCase(),cursor=$('dsql-sql').selectionStart,beforeCursor=text.slice(0,cursor);const tables=new Set();let match;const fromPattern=/\bFROM\s+([\w."]+)/gi;while((match=fromPattern.exec(beforeCursor))){tables.add(match[1].toLowerCase())}const joinPattern=/\bJOIN\s+([\w."]+)/gi;while((match=joinPattern.exec(beforeCursor))){tables.add(match[1].toLowerCase())}return tables}
function getAutocompletes(){const context=getSqlContext(),tableNames=extractTableNames(),list=[];if(context.inFrom){dsqlTables.forEach(table=>{list.push({text:quoteIdentifier(table.name),label:table.name,type:'table',schema:table.schema});list.push({text:`${quoteIdentifier(table.schema)}.${quoteIdentifier(table.name)}`,label:`${table.schema}.${table.name}`,type:'table',schema:table.schema})})}else {let availableTables=dsqlTables;if(tableNames.size>0){availableTables=dsqlTables.filter(table=>{const full=`${table.schema}.${table.name}`.toLowerCase();return tableNames.has(full)||tableNames.has(table.name.toLowerCase())})}availableTables.forEach(table=>{table.columns.forEach(col=>{list.push({text:quoteIdentifier(col.name),label:col.name,type:'column',typeHint:col.type,pk:col.primaryKey})})})}SQL_KEYWORDS.forEach(kw=>{list.push({text:kw,label:kw,type:'keyword'})});return list}
function getCurrentWord(){const text=$('dsql-sql').value,cursor=$('dsql-sql').selectionStart;let start=cursor;while(start>0&&/[a-zA-Z0-9_."]/.test(text[start-1]))start--;return {word:text.slice(start,cursor),start,end:cursor}}
function getEditorCursorCoords(){const editor=$('dsql-sql'),text=editor.value,cursor=editor.selectionStart,textBeforeCursor=text.slice(0,cursor),lines=textBeforeCursor.split('\n'),lineNum=lines.length-1,currentLine=lines[lineNum];return {x:currentLine.length*7,y:lineNum*22}}
function matchesCurrentWord(match,word){if(!word)return true;const needle=word.toLowerCase().replaceAll('"','');return match.text.toLowerCase().replaceAll('"','').startsWith(needle)||match.label.toLowerCase().startsWith(needle)}
function currentAutocompletes(){const w=getCurrentWord();return getAutocompletes().filter(m=>matchesCurrentWord(m,w.word))}
function hideAutocomplete(){acSelected=-1;acMatches=[];$('sql-autocomplete').classList.remove('show')}
function autocompleteOpen(){return $('sql-autocomplete').classList.contains('show')&&acMatches.length>0}
function showAutocomplete(matches){const ac=$('sql-autocomplete'),editor=$('dsql-sql');if(!matches.length){hideAutocomplete();return}acMatches=matches.slice(0,30);acSelected=getCurrentWord().word?0:-1;ac.innerHTML=acMatches.map((m,i)=>`<div class="sql-autocomplete-item${i===acSelected?' selected':''}" data-index="${i}" title="${esc(m.label)}"><span>${esc(m.label)}</span>${m.type==='keyword'?'':m.type==='table'?'<small>table</small>':'<small>'+esc(m.typeHint||'col')+(m.pk?'·PK':'')+'</small>'}</div>`).join('');ac.classList.add('show');ac.scrollTop=0;const coords=getEditorCursorCoords();ac.style.position='absolute';ac.style.left=`${Math.max(0,editor.offsetLeft+coords.x)}px`;ac.style.top=`${editor.offsetTop+coords.y+22}px`}
function moveAcSelection(delta){const items=document.querySelectorAll('.sql-autocomplete-item');if(!items.length)return;acSelected=(acSelected+delta+items.length)%items.length;items.forEach((it,i)=>it.classList.toggle('selected',i===acSelected));items[acSelected].scrollIntoView({block:'nearest'})}
function acceptAutocomplete(match){if(!match)return hideAutocomplete();const w=getCurrentWord();$('dsql-sql').value=$('dsql-sql').value.slice(0,w.start)+match.text+$('dsql-sql').value.slice(w.end);$('dsql-sql').selectionStart=$('dsql-sql').selectionEnd=w.start+match.text.length;hideAutocomplete();$('dsql-sql').focus()}
function shortVersion(version=''){return version.split(/[,(]/)[0].trim()||'Aurora DSQL'}
function renderDsqlTables(){const needle=$('dsql-filter').value.trim().toLowerCase(),matches=(table)=>!needle||`${table.schema}.${table.name}`.toLowerCase().includes(needle)||table.columns.some(c=>c.name.toLowerCase().includes(needle));visibleDsqlTables=dsqlTables.filter(matches);$('dsql-tables').innerHTML=visibleDsqlTables.map((table,index)=>`<details${needle&&visibleDsqlTables.length<9?' open':''}><summary><span class="table-schema">${esc(table.schema)}.</span>${esc(table.name)}<button class="select-table" data-select-table="${index}" title="Query this table">▷</button><small>${table.columns.length} cols</small></summary>${table.columns.map(column=>`<button class="column" data-column="${esc(qualify(table,column.name))}"><span>${esc(column.name)}</span>${column.primaryKey?'<b>PK</b>':''}<em>${esc(column.type)}${column.nullable?'':' · not null'}</em></button>`).join('')}</details>`).join('')||`<div class="empty">${dsqlTables.length?'No tables match this filter.':'This cluster has no user tables.'}</div>`}
function quoteIdentifier(name){return /^[a-z_][a-z0-9_]*$/.test(name)?name:`"${name.replaceAll('"','""')}"`}
function qualify(table,column){return `${quoteIdentifier(table.schema)}.${quoteIdentifier(table.name)}.${quoteIdentifier(column)}`}
function insertSql(text){const editor=$('dsql-sql'),start=editor.selectionStart??editor.value.length,end=editor.selectionEnd??start;editor.value=`${editor.value.slice(0,start)}${text}${editor.value.slice(end)}`;editor.focus();editor.selectionStart=editor.selectionEnd=start+text.length}
function rowLimit(){return Math.min(Math.max(Number($('dsql-limit').value)||200,1),1000)}
function selectFromTable(index){const table=visibleDsqlTables[index];if(!table)return;$('dsql-sql').value=`SELECT *\nFROM ${quoteIdentifier(table.schema)}.${quoteIdentifier(table.name)}\nLIMIT ${rowLimit()};`;runSql()}
async function runSql(){if(!$('cluster-select').value)return toast('This stack has no Aurora DSQL clusters');const button=$('run-sql');button.classList.add('loading');$('dsql-results').classList.add('loading');try{const result=await post('/api/dsql/query',{clusterName:$('cluster-select').value,sql:$('dsql-sql').value,limit:rowLimit()});lastSqlResult=result;recordDsqlQuery($('dsql-sql').value,$('cluster-select').value);renderSqlResult(result);$('dsql-meta').innerHTML=`${esc(result.command||'SELECT')} · ${result.rows.length} row${result.rows.length===1?'':'s'} · ${result.durationMs}ms${result.truncated?` · capped at ${result.limit} of ${result.returned}`:''}${result.readOnlyTransaction?'':' · <span class="readonly-note">read-only transaction unavailable on this cluster</span>'}`}catch(e){toast(e.message);$('dsql-meta').textContent=e.message;$('dsql-results').innerHTML=`<div class="preview-error">${esc(e.message)}</div>`}finally{button.classList.remove('loading');$('dsql-results').classList.remove('loading')}}
function loadDsqlHistory(){try{const stored=JSON.parse(localStorage.getItem(DSQL_HISTORY_KEY)||localStorage.getItem(LEGACY_DSQL_HISTORY_KEY)||'[]');dsqlHistory=Array.isArray(stored)?stored.filter(entry=>entry&&typeof entry.sql==='string'&&entry.sql.trim()).map(entry=>({sql:entry.sql,cluster:entry.cluster||'',at:Number(entry.at)||Date.now(),count:Number(entry.count)||1,pinned:!!entry.pinned})):[]}catch{dsqlHistory=[]}sortDsqlHistory();renderDsqlHistory()}
function persistDsqlHistory(){try{localStorage.setItem(DSQL_HISTORY_KEY,JSON.stringify(dsqlHistory))}catch{toast('This browser is not letting StackEye save query history')}}
function sortDsqlHistory(){dsqlHistory.sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.at-a.at)}
function historyKey(sql){return sql.replace(/\s+/g,' ').trim().replace(/;$/,'').toLowerCase()}
function recordDsqlQuery(sql,cluster){const text=sql.trim();if(!text)return;const index=dsqlHistory.findIndex(entry=>entry.cluster===cluster&&historyKey(entry.sql)===historyKey(text)),previous=index<0?undefined:dsqlHistory.splice(index,1)[0];dsqlHistory.unshift({sql:text,cluster,at:Date.now(),count:(previous?.count||0)+1,pinned:!!previous?.pinned});sortDsqlHistory();dsqlHistory=[...dsqlHistory.filter(entry=>entry.pinned),...dsqlHistory.filter(entry=>!entry.pinned).slice(0,DSQL_HISTORY_MAX)];persistDsqlHistory();renderDsqlHistory()}
function historyAgo(at){const seconds=Math.max(0,Date.now()-at)/1000;if(seconds<60)return 'just now';if(seconds<3600)return `${Math.floor(seconds/60)}m ago`;if(seconds<86400)return `${Math.floor(seconds/3600)}h ago`;if(seconds<604800)return `${Math.floor(seconds/86400)}d ago`;return new Date(at).toLocaleDateString()}
function renderDsqlHistory(){const list=$('dsql-history'),cluster=$('cluster-select').value;if(!dsqlHistory.length)return list.innerHTML='<div class="empty">Queries you run are saved here, on this device only.</div>';list.innerHTML=dsqlHistory.map((entry,index)=>{const preview=entry.sql.replace(/\s+/g,' ').trim(),meta=[historyAgo(entry.at),entry.count>1?`ran ${entry.count}×`:'',entry.cluster&&entry.cluster!==cluster?entry.cluster:''].filter(Boolean).join(' · ');return `<div class="history-item${entry.pinned?' pinned':''}"><button class="history-sql" data-load="${index}" title="Load into the editor"><code>${esc(preview.length>150?`${preview.slice(0,150)}…`:preview)}</code><small>${esc(meta)}</small></button><button class="history-act" data-pin="${index}" title="${entry.pinned?'Unpin':'Pin so it survives Clear'}">${entry.pinned?'★':'☆'}</button><button class="history-act" data-run="${index}" title="Load and run">▶</button><button class="history-act" data-drop="${index}" title="Remove">×</button></div>`}).join('')}
function loadHistoryQuery(index){const entry=dsqlHistory[index];if(!entry)return;const select=$('cluster-select');if(entry.cluster&&entry.cluster!==select.value&&[...select.options].some(option=>option.value===entry.cluster)){select.value=entry.cluster;select.onchange()}const editor=$('dsql-sql');editor.value=entry.sql;hideAutocomplete();editor.focus();editor.selectionStart=editor.selectionEnd=entry.sql.length;return entry}
function clearDsqlHistory(){if(!dsqlHistory.length)return;const pinned=dsqlHistory.filter(entry=>entry.pinned),dropping=dsqlHistory.length-pinned.length;if(!dropping)return toast('Every saved query is pinned — unpin the ones you want to drop');if(!confirm(`Remove ${dropping} saved quer${dropping===1?'y':'ies'} from this device?${pinned.length?`\n\n${pinned.length} pinned quer${pinned.length===1?'y':'ies'} will be kept.`:''}`))return;dsqlHistory=pinned;persistDsqlHistory();renderDsqlHistory()}
function renderSqlResult(result){const fields=result.fields||[],rows=result.rows||[];if(!fields.length)return $('dsql-results').innerHTML='<div class="empty">The statement returned no columns.</div>';if(!rows.length)return $('dsql-results').innerHTML='<div class="empty">No rows returned.</div>';$('dsql-results').innerHTML=`<table><thead><tr>${fields.map(f=>`<th>${esc(f.name)}<span class="field-type">${esc(f.type)}</span></th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${fields.map((_,index)=>`<td>${row[index]===null?'<span class="sql-null">NULL</span>':renderCell(row[index])}</td>`).join('')}</tr>`).join('')}</tbody></table>`}

function s3Params(extra={}){return new URLSearchParams({bucketName:$('bucket-select').value,...extra})}
