async function pollLogs() {
  const params = new URLSearchParams({ functionName:$('log-function').value, startTime:String(Date.now()-15*60000) });
  if (token) params.set('nextToken',token); if ($('filter').value) params.set('filterPattern',$('filter').value);
  try { const data=await api(`/api/logs?${params}`); token=data.nextToken; appendLogs(data.events); $('log-state').textContent=`Tailing /aws/lambda/${$('log-function').selectedOptions[0]?.text}`; }
  catch(e){ toast(`Logs: ${e.message}`); stopTail(); }
}
function appendLogs(events) { const fresh=events.filter(e=>!seen.has(e.id)); fresh.forEach(e=>seen.add(e.id)); if(!fresh.length)return; if($('terminal').querySelector('.terminal-empty'))$('terminal').innerHTML=''; $('terminal').insertAdjacentHTML('beforeend',fresh.map(e=>`<div class="log-line ${/error|exception|fatal/i.test(e.message)?'error':/warn/i.test(e.message)?'warn':''}"><time>${new Date(e.timestamp).toLocaleTimeString()}</time><span class="stream">${esc(e.stream)}</span><span class="message">${esc(e.message.trimEnd())}</span></div>`).join('')); eventCount+=fresh.length;$('event-count').textContent=`${eventCount} events`;$('terminal').scrollTop=$('terminal').scrollHeight; }
