/* Aurora DSQL ER diagram — table cards positioned by dependency depth, joined by
   crow's-foot connectors drawn from the live DOM geometry of each column row. */
const ERD_PAD=44,ERD_COL_GAP=118,ERD_ROW_GAP=30,ERD_MAX_ROWS=16,ERD_MAX_COLUMN_HEIGHT=1000;
const ERD_TYPES={'character varying':'varchar','character':'char','timestamp without time zone':'timestamp','timestamp with time zone':'timestamptz','time without time zone':'time','time with time zone':'timetz','double precision':'float8','boolean':'bool','integer':'int','smallint':'int2','bigint':'int8','numeric':'numeric','ARRAY':'array','USER-DEFINED':'enum'};
let erdRelationships=[],erdPositions=new Map(),erdBounds={width:0,height:0},erdZoom=1,erdKeysOnly=false,erdInferred=true,erdReferencing=new Set(),erdReferenced=new Set();
function erdTableId(table){return `${table.schema}.${table.name}`}
function erdShortType(type=''){return ERD_TYPES[type]||type}
function erdNode(id){return document.querySelector(`.erd-node[data-erd-node="${CSS.escape(id)}"]`)}
function erdPaneActive(){return $('dsql').classList.contains('active')&&Boolean(document.querySelector('.dsql-pane.active[data-dsql-pane="erd"]'))}
function setDsqlTab(name){document.querySelectorAll('.dsql-tabs button').forEach(button=>button.classList.toggle('active',button.dataset.dsqlTab===name));document.querySelectorAll('.dsql-pane').forEach(pane=>pane.classList.toggle('active',pane.dataset.dsqlPane===name));if(name==='erd')renderErd()}
function erdEdges(){const known=new Set(dsqlTables.map(erdTableId));return erdRelationships.filter(edge=>known.has(edge.source)&&known.has(edge.target)&&(erdInferred||edge.declared))}
function erdMarkKeyColumns(edges){erdReferencing=new Set(edges.flatMap(edge=>edge.columns.map(pair=>`${edge.source}.${pair.from}`)));erdReferenced=new Set(edges.flatMap(edge=>edge.columns.map(pair=>`${edge.target}.${pair.to}`)))}
function updateErdTabCount(){$('erd-tab-count').textContent=dsqlTables.length?String(dsqlTables.length):''}

// Wide tables are trimmed rather than turned into towers: keys always stay on the
// card, because they are what the connectors have to attach to.
function erdCardColumns(table){
  const id=erdTableId(table),keyed=(column)=>column.primaryKey||erdReferencing.has(`${id}.${column.name}`)||erdReferenced.has(`${id}.${column.name}`);
  if(erdKeysOnly){const shown=table.columns.filter(keyed);return {shown:shown.length?shown:table.columns.slice(0,1),hidden:table.columns.length-(shown.length||1)}}
  if(table.columns.length<=ERD_MAX_ROWS)return {shown:table.columns,hidden:0};
  const kept=table.columns.filter(keyed);table.columns.forEach(column=>{if(kept.length<ERD_MAX_ROWS&&!kept.includes(column))kept.push(column)});
  return {shown:table.columns.filter(column=>kept.includes(column)),hidden:table.columns.length-kept.length};
}
function erdCardHtml(table){const id=erdTableId(table),{shown,hidden}=erdCardColumns(table);return `<article class="erd-node" data-erd-node="${esc(id)}"><header><span class="erd-name"><small>${esc(table.schema)}.</small>${esc(table.name)}</span>${table.kind==='view'?'<i class="erd-kind">VIEW</i>':''}<button class="erd-query" data-erd-query="${esc(id)}" title="Query this table">▷</button></header><ul>${shown.map(column=>erdColumnHtml(id,column)).join('')}</ul>${hidden>0?`<footer>+ ${hidden} more column${hidden===1?'':'s'}</footer>`:''}</article>`}
function erdColumnHtml(id,column){const reference=erdReferencing.has(`${id}.${column.name}`),classes=[column.primaryKey?'pk':reference?'fk':'',column.nullable?'':'required'].filter(Boolean).join(' ');return `<li data-erd-column="${esc(column.name)}"${classes?` class="${classes}"`:''}><span class="erd-glyph">${column.primaryKey?'◆':reference?'◇':'·'}</span><b>${esc(column.name)}</b><em>${esc(erdShortType(column.type))}</em></li>`}

function erdEmptyMessage(){if(!$('cluster-select').value)return 'This stack has no Aurora DSQL clusters.';if(dsqlLoaded)return 'This cluster has no user tables.';return 'The cluster schema could not be read — see the message above the tabs.'}
function renderErd(){
  if(!erdPaneActive())return;
  updateErdTabCount();
  if(!dsqlTables.length){$('erd-viewport').innerHTML=`<div class="empty">${esc(erdEmptyMessage())}</div>`;renderErdRelationships([]);updateErdSummary([]);return}
  const edges=erdEdges();erdMarkKeyColumns(edges);
  $('erd-viewport').innerHTML=`<div class="erd-stage" id="erd-stage"><div class="erd-canvas" id="erd-canvas"><svg class="erd-lines" id="erd-lines"></svg>${dsqlTables.map(erdCardHtml).join('')}</div></div>`;
  const nodes=dsqlTables.map(table=>{const id=erdTableId(table),element=erdNode(id);return {id,element,w:element.offsetWidth,h:element.offsetHeight}});
  const layout=layoutErd(nodes,edges),fresh=!erdPositions.size;
  nodes.forEach(node=>{const position=erdPositions.get(node.id)||layout.get(node.id);erdPositions.set(node.id,position);node.element.style.left=`${position.x}px`;node.element.style.top=`${position.y}px`});
  resizeErdCanvas();drawErdEdges(edges);renderErdRelationships(edges);updateErdSummary(edges);highlightErdSearch();
  if(fresh)fitErd(); // a freshly laid out diagram opens fully visible rather than cropped
}

// Rank = how deep a table sits in the chain of references it depends on, so the
// tables everything points at land on the left and the leaves on the right.
function layoutErd(nodes,edges){
  const size=new Map(nodes.map(node=>[node.id,node])),parents=new Map(),children=new Map(),ids=nodes.map(node=>node.id);
  edges.forEach(edge=>{if(edge.source===edge.target||!size.has(edge.source)||!size.has(edge.target))return;erdPush(parents,edge.source,edge.target);erdPush(children,edge.target,edge.source)});
  const ranks=erdRanks(ids,parents),group=erdComponents(ids,parents,children),linked=(id)=>(parents.get(id)?.length||0)+(children.get(id)?.length||0)>0;
  const ranked=[];ids.filter(linked).forEach(id=>{const rank=ranks.get(id);(ranked[rank]=ranked[rank]||[]).push(id)});
  const columns=[];ranked.filter(Boolean).forEach(rank=>{rank.sort((a,b)=>group.get(a)-group.get(b)||a.localeCompare(b));columns.push(...erdSplitRank(rank,size))});
  const order=new Map();columns.forEach(column=>column.forEach((id,row)=>order.set(id,row)));
  for(let pass=0;pass<4;pass++)erdOrderColumns(pass%2?[...columns].reverse():columns,parents,children,group,order);
  const positions=new Map();let x=ERD_PAD;
  columns.forEach(column=>{let y=ERD_PAD;column.forEach(id=>{positions.set(id,{x,y});y+=size.get(id).h+ERD_ROW_GAP});x+=Math.max(...column.map(id=>size.get(id).w))+ERD_COL_GAP});
  for(let pass=0;pass<3;pass++)columns.forEach(column=>erdAlignColumn(column,positions,size,parents,children));
  const top=Math.min(...[...positions.values()].map(position=>position.y)); // alignment passes only ever push down, so pull the whole graph back up
  if(Number.isFinite(top))positions.forEach(position=>{position.y-=top-ERD_PAD});
  erdPlaceUnlinked(nodes.filter(node=>!linked(node.id)),positions,size,x);
  return positions;
}
// A rank holding dozens of tables — twenty event tables all pointing at orders —
// would stretch the diagram into an unreadable ribbon, so it wraps into columns.
function erdSplitRank(rank,size){
  const chunks=[[]];let height=0;
  rank.forEach(id=>{
    const step=size.get(id).h+ERD_ROW_GAP;
    if(chunks.at(-1).length&&height+step>ERD_MAX_COLUMN_HEIGHT){chunks.push([]);height=0}
    chunks.at(-1).push(id);height+=step;
  });
  return chunks;
}
function erdPush(map,key,value){const list=map.get(key)||[];list.push(value);map.set(key,list)}
function erdRanks(ids,parents){
  const ranks=new Map(),visiting=new Set();
  const rankOf=(id)=>{
    if(ranks.has(id))return ranks.get(id);
    if(visiting.has(id))return 0; // a reference cycle has no depth to speak of
    visiting.add(id);
    const rank=(parents.get(id)||[]).reduce((depth,parent)=>Math.max(depth,rankOf(parent)+1),0);
    visiting.delete(id);ranks.set(id,rank);return rank;
  };
  ids.forEach(rankOf);return ranks;
}
function erdComponents(ids,parents,children){
  const group=new Map();let index=0;
  ids.forEach(start=>{
    if(group.has(start))return;
    const queue=[start];group.set(start,index);
    while(queue.length){const id=queue.pop();[...(parents.get(id)||[]),...(children.get(id)||[])].forEach(next=>{if(!group.has(next)){group.set(next,index);queue.push(next)}})}
    index++;
  });
  return group;
}
function erdOrderColumns(columns,parents,children,group,order){columns.forEach(column=>{const centre=new Map(column.map(id=>{const neighbours=erdNeighbours(id,parents,children).filter(next=>order.has(next));return [id,neighbours.length?neighbours.reduce((sum,next)=>sum+order.get(next),0)/neighbours.length:order.get(id)]}));column.sort((a,b)=>group.get(a)-group.get(b)||centre.get(a)-centre.get(b)||a.localeCompare(b));column.forEach((id,row)=>order.set(id,row))})}
function erdAlignColumn(column,positions,size,parents,children){
  const wanted=column.map(id=>{const neighbours=erdNeighbours(id,parents,children).filter(next=>positions.has(next)),middle=positions.get(id).y+size.get(id).h/2;
    return {id,centre:neighbours.length?neighbours.reduce((sum,next)=>sum+positions.get(next).y+size.get(next).h/2,0)/neighbours.length:middle}});
  wanted.sort((a,b)=>a.centre-b.centre);
  let y=ERD_PAD;
  wanted.forEach(entry=>{const height=size.get(entry.id).h,top=Math.max(y,Math.round(entry.centre-height/2));positions.get(entry.id).y=top;y=top+height+ERD_ROW_GAP});
  column.sort((a,b)=>positions.get(a).y-positions.get(b).y);
}
function erdNeighbours(id,parents,children){return [...(parents.get(id)||[]),...(children.get(id)||[])]}
function erdPlaceUnlinked(nodes,positions,size,columnsWidth){
  if(!nodes.length)return;
  const used=[...positions.entries()],limit=Math.max(columnsWidth,880);
  let x=ERD_PAD,y=used.length?Math.max(...used.map(([id,position])=>position.y+size.get(id).h))+70:ERD_PAD,tallest=0;
  nodes.forEach(node=>{
    if(x>ERD_PAD&&x+node.w>limit){x=ERD_PAD;y+=tallest+ERD_ROW_GAP;tallest=0}
    positions.set(node.id,{x,y});x+=node.w+ERD_COL_GAP/2;tallest=Math.max(tallest,node.h);
  });
}

function resizeErdCanvas(){
  const nodes=[...document.querySelectorAll('.erd-node')];if(!nodes.length)return;
  erdBounds={width:Math.max(...nodes.map(node=>node.offsetLeft+node.offsetWidth))+ERD_PAD,height:Math.max(...nodes.map(node=>node.offsetTop+node.offsetHeight))+ERD_PAD};
  $('erd-canvas').style.width=`${erdBounds.width}px`;$('erd-canvas').style.height=`${erdBounds.height}px`;
  $('erd-lines').setAttribute('width',erdBounds.width);$('erd-lines').setAttribute('height',erdBounds.height);
  applyErdZoom();
}
function drawErdEdges(edges){const lines=$('erd-lines');if(lines)lines.innerHTML=edges.map(erdEdgeSvg).filter(Boolean).join('')}
function erdEdgeSvg(edge){
  const source=erdNode(edge.source),target=erdNode(edge.target);
  if(!source||!target)return '';
  const from=erdBox(source),to=erdBox(target),pair=edge.columns[0];
  const fromY=from.y+erdAnchorY(source,pair.from),toY=to.y+erdAnchorY(target,pair.to);
  const shape=edge.source===edge.target?erdSelfShape(from,fromY,toY,edge):erdShape(from,fromY,to,toY,edge);
  const classes=['erd-edge',edge.declared?'declared':'inferred',edge.optional?'optional':''].filter(Boolean).join(' ');
  return `<g class="${classes}" data-erd-source="${esc(edge.source)}" data-erd-target="${esc(edge.target)}" data-erd-from="${esc(pair.from)}" data-erd-to="${esc(pair.to)}"><title>${esc(erdEdgeTitle(edge))}</title><path class="erd-hit" d="${shape.path}"/><path class="erd-link" d="${shape.path}"/><path class="erd-tick" d="${shape.tick}"/>${edge.optional?`<circle class="erd-optional-dot" cx="${shape.dot.x}" cy="${shape.dot.y}" r="3.2"/>`:''}</g>`;
}
function erdBox(element){return {x:element.offsetLeft,y:element.offsetTop,w:element.offsetWidth,h:element.offsetHeight}}
function erdAnchorY(element,column){const row=[...element.querySelectorAll('[data-erd-column]')].find(item=>item.dataset.erdColumn===column);return row?row.offsetTop+row.offsetHeight/2:element.querySelector('header').offsetHeight/2}
function erdShape(from,fromY,to,toY,edge){
  const rightward=to.x>=from.x+from.w+24,leftward=from.x>=to.x+to.w+24;
  const fromSide=leftward?-1:1,toSide=rightward?-1:1;
  const fromX=fromSide>0?from.x+from.w:from.x,toX=toSide>0?to.x+to.w:to.x;
  const reach=rightward||leftward?Math.max(46,Math.min(160,Math.abs(toX-fromX)*0.5)):80+Math.min(90,Math.abs(toY-fromY)*0.25);
  return {path:`M ${fromX} ${fromY} C ${fromX+fromSide*reach} ${fromY}, ${toX+toSide*reach} ${toY}, ${toX} ${toY}`,
    tick:`${erdFootPath(fromX,fromY,fromSide,edge.unique)} ${erdBarPath(toX,toY,toSide)}`,dot:{x:fromX+fromSide*17,y:fromY}};
}
function erdSelfShape(box,fromY,toY,edge){
  const x=box.x+box.w,end=Math.abs(toY-fromY)<6?toY+11:toY,reach=64;
  return {path:`M ${x} ${fromY} C ${x+reach} ${fromY}, ${x+reach} ${end}, ${x} ${end}`,
    tick:`${erdFootPath(x,fromY,1,edge.unique)} ${erdBarPath(x,end,1)}`,dot:{x:x+17,y:fromY}};
}
function erdFootPath(x,y,side,unique){return unique?`M ${x+side*10} ${y-5.5} L ${x+side*10} ${y+5.5}`:`M ${x+side*11} ${y} L ${x} ${y-4.6} M ${x+side*11} ${y} L ${x} ${y} M ${x+side*11} ${y} L ${x} ${y+4.6}`}
function erdBarPath(x,y,side){return `M ${x+side*9} ${y-5.5} L ${x+side*9} ${y+5.5}`}
function erdCardinality(edge){return edge.unique?(edge.optional?'0..1 → 1':'1 → 1'):(edge.optional?'0..N → 1':'N → 1')}
function erdEdgeTitle(edge){return `${edge.source}.${edge.columns.map(pair=>pair.from).join(', ')} → ${edge.target}.${edge.columns.map(pair=>pair.to).join(', ')} · ${edge.cardinality}${edge.optional?' · optional':''} · ${edge.declared?`foreign key ${edge.name}`:`inferred, ${edge.confidence} confidence`}`}

function setErdFocus(id){
  const canvas=$('erd-canvas');if(!canvas)return;
  const related=new Set(id?[id]:[]);
  canvas.querySelectorAll('.lit').forEach(row=>row.classList.remove('lit'));
  canvas.querySelectorAll('.erd-edge').forEach(edge=>{const hit=edge.dataset.erdSource===id||edge.dataset.erdTarget===id;if(hit){related.add(edge.dataset.erdSource);related.add(edge.dataset.erdTarget)}edge.classList.toggle('is-related',hit)});
  canvas.classList.toggle('focus-active',Boolean(id));
  canvas.querySelectorAll('.erd-node').forEach(node=>node.classList.toggle('is-related',related.has(node.dataset.erdNode)));
}
function focusErdEdge(group){
  const canvas=$('erd-canvas'),{erdSource,erdTarget,erdFrom,erdTo}=group.dataset;
  canvas.querySelectorAll('.lit').forEach(row=>row.classList.remove('lit'));
  canvas.querySelectorAll('.erd-edge').forEach(edge=>edge.classList.toggle('is-related',edge===group));
  canvas.classList.add('focus-active');
  canvas.querySelectorAll('.erd-node').forEach(node=>node.classList.toggle('is-related',[erdSource,erdTarget].includes(node.dataset.erdNode)));
  erdColumnRow(erdSource,erdFrom)?.classList.add('lit');erdColumnRow(erdTarget,erdTo)?.classList.add('lit');
}
function erdColumnRow(id,column){return [...(erdNode(id)?.querySelectorAll('[data-erd-column]')||[])].find(row=>row.dataset.erdColumn===column)}

function renderErdRelationships(edges){
  const list=$('erd-rel-list');
  if(!edges.length)return void(list.innerHTML=`<div class="empty">${dsqlTables.length?'No relationships between these tables.':'Relationships appear here.'}</div>`);
  list.innerHTML=[...edges].sort((a,b)=>a.source.localeCompare(b.source)||a.columns[0].from.localeCompare(b.columns[0].from)).map(edge=>`<button class="erd-rel${edge.declared?'':' inferred'}" data-erd-reveal="${esc(edge.source)}"><span>${esc(edge.source)}<span class="erd-rel-column">.${esc(edge.columns.map(pair=>pair.from).join(', '))}</span></span><span class="erd-rel-arrow">${erdCardinality(edge)}</span><span>${esc(edge.target)}<span class="erd-rel-column">.${esc(edge.columns.map(pair=>pair.to).join(', '))}</span></span><span class="erd-rel-badge">${edge.declared?'foreign key':`inferred · ${esc(edge.confidence)}`}</span></button>`).join('');
}
function updateErdSummary(edges){
  const declared=edges.filter(edge=>edge.declared).length,inferred=edges.length-declared,note=$('erd-note');
  $('erd-summary').textContent=`${dsqlTables.length} table${dsqlTables.length===1?'':'s'} · ${edges.length} relationship${edges.length===1?'':'s'}${inferred?` · ${inferred} inferred`:''}`;
  note.classList.toggle('hidden',Boolean(declared)||!dsqlTables.length);
  if(!declared&&dsqlTables.length)note.textContent=`No foreign key constraints exist in this database — Aurora DSQL does not support them. ${inferred?`The ${inferred} relationship${inferred===1?'':'s'} above ${inferred===1?'was':'were'} inferred from column names, primary keys, and matching types, so read ${inferred===1?'it':'them'} as a hint rather than a contract.`:'Nothing could be inferred from column names either, so the tables are shown on their own.'}`;
}

function applyErdZoom(){
  const canvas=$('erd-canvas'),stage=$('erd-stage');if(!canvas||!stage)return;
  canvas.style.transform=`scale(${erdZoom})`;stage.style.width=`${erdBounds.width*erdZoom}px`;stage.style.height=`${erdBounds.height*erdZoom}px`;
  $('erd-zoom-level').textContent=`${Math.round(erdZoom*100)}%`;
}
function setErdZoom(value){erdZoom=Math.min(1.7,Math.max(0.3,Math.round(value*100)/100));applyErdZoom()}
function fitErd(){const viewport=$('erd-viewport');if(!erdBounds.width)return;setErdZoom(Math.min(1,(viewport.clientWidth-10)/erdBounds.width,(viewport.clientHeight-10)/erdBounds.height));viewport.scrollTo({left:0,top:0})}
function highlightErdSearch(){
  const needle=$('erd-search').value.trim().toLowerCase(),canvas=$('erd-canvas');if(!canvas)return;
  const matches=new Set(needle?dsqlTables.filter(table=>erdTableId(table).toLowerCase().includes(needle)||table.columns.some(column=>column.name.toLowerCase().includes(needle))).map(erdTableId):[]);
  let first;
  canvas.querySelectorAll('.erd-node').forEach(node=>{const hit=matches.has(node.dataset.erdNode);node.classList.toggle('is-match',hit);if(hit&&!first)first=node});
  if(first)erdScrollTo(first);
}
function erdScrollTo(node){$('erd-viewport').scrollTo({left:Math.max(0,node.offsetLeft*erdZoom-90),top:Math.max(0,node.offsetTop*erdZoom-90),behavior:'smooth'})}
function revealErdTable(id){const node=erdNode(id);if(!node)return;erdScrollTo(node);setErdFocus(id)}
function queryErdTable(id){const table=dsqlTables.find(candidate=>erdTableId(candidate)===id);if(!table)return;$('dsql-sql').value=`SELECT *\nFROM ${quoteIdentifier(table.schema)}.${quoteIdentifier(table.name)}\nLIMIT ${rowLimit()};`;setDsqlTab('query');runSql()}

function startErdDrag(node,event){
  const id=node.dataset.erdNode,start={x:event.clientX,y:event.clientY},origin={...erdPositions.get(id)};
  let frame=0;
  const move=(moved)=>{
    const position=erdPositions.get(id);
    position.x=Math.max(8,Math.round(origin.x+(moved.clientX-start.x)/erdZoom));
    position.y=Math.max(8,Math.round(origin.y+(moved.clientY-start.y)/erdZoom));
    node.style.left=`${position.x}px`;node.style.top=`${position.y}px`;
    if(!frame)frame=requestAnimationFrame(()=>{frame=0;drawErdEdges(erdEdges())});
  };
  const stop=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop);node.classList.remove('dragging');resizeErdCanvas();drawErdEdges(erdEdges())};
  node.classList.add('dragging');window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);
}
function startErdPan(event){
  const viewport=$('erd-viewport'),start={x:event.clientX,y:event.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};
  const move=(moved)=>{viewport.scrollLeft=start.left-(moved.clientX-start.x);viewport.scrollTop=start.top-(moved.clientY-start.y)};
  const stop=()=>{viewport.classList.remove('panning');window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop)};
  viewport.classList.add('panning');window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);
}

// Mermaid is the lingua franca for pasting a schema into a design doc or a PR.
function erdMermaid(edges){
  const entity=(id)=>id.replace(/[^A-Za-z0-9_]/g,'_'),lines=['erDiagram'];
  dsqlTables.forEach(table=>{
    lines.push(`  ${entity(erdTableId(table))} {`);
    table.columns.forEach(column=>{const flags=[column.primaryKey?'PK':'',erdReferencing.has(`${erdTableId(table)}.${column.name}`)?'FK':''].filter(Boolean).join(',');lines.push(`    ${entity(erdShortType(column.type))} ${entity(column.name)}${flags?` ${flags}`:''}`)});
    lines.push('  }');
  });
  edges.forEach(edge=>{const link=edge.unique?(edge.optional?'||--o|':'||--||'):(edge.optional?'||--o{':'||--|{');lines.push(`  ${entity(edge.target)} ${link} ${entity(edge.source)} : "${edge.columns.map(pair=>pair.from).join(', ')}"`)});
  return lines.join('\n');
}

document.querySelector('.dsql-tabs').onclick=(event)=>{const button=event.target.closest('button');if(button)setDsqlTab(button.dataset.dsqlTab)};
$('erd-search').oninput=highlightErdSearch;
$('erd-inferred').onchange=()=>{erdInferred=$('erd-inferred').checked;renderErd()};
$('erd-keys-only').onchange=()=>{erdKeysOnly=$('erd-keys-only').checked;erdPositions.clear();renderErd()};
$('erd-relayout').onclick=()=>{erdPositions.clear();renderErd();fitErd()};
$('erd-fit').onclick=fitErd;$('erd-zoom-in').onclick=()=>setErdZoom(erdZoom+0.15);$('erd-zoom-out').onclick=()=>setErdZoom(erdZoom-0.15);
$('erd-copy').onclick=async()=>{if(!dsqlTables.length)return toast('Load a cluster schema first');await navigator.clipboard.writeText(erdMermaid(erdEdges()));toast('Mermaid ER diagram copied')};
$('erd-viewport').addEventListener('pointerdown',(event)=>{if(event.button!==0)return;const node=event.target.closest('.erd-node');if(node&&!event.target.closest('.erd-query'))startErdDrag(node,event);else if(!node)startErdPan(event)});
$('erd-viewport').addEventListener('wheel',(event)=>{if(!event.ctrlKey&&!event.metaKey)return;event.preventDefault();setErdZoom(erdZoom-Math.sign(event.deltaY)*0.08)},{passive:false});
$('erd-viewport').addEventListener('mouseover',(event)=>{const edge=event.target.closest('.erd-edge'),node=event.target.closest('.erd-node');if(edge)focusErdEdge(edge);else if(node)setErdFocus(node.dataset.erdNode)});
$('erd-viewport').addEventListener('mouseout',(event)=>{const target=event.target.closest('.erd-edge,.erd-node');if(target&&!target.contains(event.relatedTarget))setErdFocus(null)});
$('erd-viewport').onclick=(event)=>{const query=event.target.closest('[data-erd-query]');if(query)queryErdTable(query.dataset.erdQuery)};
$('erd-rel-list').onclick=(event)=>{const row=event.target.closest('[data-erd-reveal]');if(row)revealErdTable(row.dataset.erdReveal)};
$('erd-rel-list').addEventListener('mouseover',(event)=>{const row=event.target.closest('[data-erd-reveal]');if(row)setErdFocus(row.dataset.erdReveal)});
$('erd-rel-list').addEventListener('mouseleave',()=>setErdFocus(null));

// Bedrock assistant — sends only the active page's rendered/structured context.
let assistantHistory=[],assistantActions=[];
function assistantPage(){return document.querySelector('.view.active')}
function assistantAttachment(){const page=assistantPage(),href=$('s3-download')?.href;if(page?.id!=='s3'||!href||$('s3-download').classList.contains('hidden'))return null;const url=new URL(href),key=url.searchParams.get('key'),extension=key?.split('.').pop().toLowerCase();return key&&['pdf','png','jpg','jpeg','gif','webp'].includes(extension)?{bucketName:$('bucket-select').value,key}:null}
function assistantContext(){const page=assistantPage(),structured={page:page?.id||'unknown',stack:context?.stack,region:context?.region,visibleText:(page?.innerText||'').slice(0,60000)};if(page?.id==='dsql')structured.dsql={cluster:$('cluster-select').value,schema:dsqlTables,currentSql:$('dsql-sql').value,visibleResult:lastSqlResult};if(page?.id==='dynamodb')structured.dynamodb={table:$('table-select').value,schema:tableDescription,visibleItems:displayedDynamoItems.slice(0,60)};if(page?.id==='architecture')structured.architecture=context.architecture;if(page?.id==='s3')structured.s3={bucket:$('bucket-select').value,prefix:s3Prefix,visibleFiles:s3Entries.slice(0,100),preview:assistantAttachment()?.key};return JSON.stringify(structured)}
function refreshAssistantContext(){const page=assistantPage(),attachment=assistantAttachment();$('assistant-context').textContent=page?.id?`${page.id} page`:'Visible page';$('assistant-attachment').classList.toggle('hidden',!attachment);$('assistant-attachment').textContent=attachment?`Attached from S3: ${attachment.key}`:''}
function assistantInlineMarkdown(text){return esc(text).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/__([^_]+)__/g,'<strong>$1</strong>').replace(/(^|[^*])\*([^*\n]+)\*/g,'$1<em>$2</em>').replace(/(^|[^_])_([^_\n]+)_/g,'$1<em>$2</em>')}
function assistantMarkdown(markdown){const lines=String(markdown||'').replace(/\r/g,'').split('\n'),html=[];let paragraph=[],list='',code=false,codeLines=[];const flushParagraph=()=>{if(paragraph.length){html.push(`<p>${assistantInlineMarkdown(paragraph.join(' '))}</p>`);paragraph=[]}},flushList=()=>{if(list){html.push(`</${list}>`);list=''}},flushCode=()=>{html.push(`<pre><code>${esc(codeLines.join('\n'))}</code></pre>`);codeLines=[]};for(const line of lines){if(/^```/.test(line.trim())){if(code){flushCode();code=false}else{flushParagraph();flushList();code=true}continue}if(code){codeLines.push(line);continue}const heading=line.match(/^(#{1,4})\s+(.+)$/),unordered=line.match(/^\s*[-*+]\s+(.+)$/),ordered=line.match(/^\s*\d+[.)]\s+(.+)$/);if(heading){flushParagraph();flushList();const level=Math.min(heading[1].length+2,6);html.push(`<h${level}>${assistantInlineMarkdown(heading[2])}</h${level}>`)}else if(unordered||ordered){flushParagraph();const next=unordered?'ul':'ol';if(list!==next){flushList();html.push(`<${next}>`);list=next}html.push(`<li>${assistantInlineMarkdown((unordered||ordered)[1])}</li>`)}else if(!line.trim()){flushParagraph();flushList()}else{flushList();paragraph.push(line.trim())}}if(code)flushCode();flushParagraph();flushList();return html.join('')}
function addAssistantMessage(role,text){$('assistant-messages').querySelector('.assistant-empty')?.remove();const body=role==='assistant'?assistantMarkdown(text):esc(text);$('assistant-messages').insertAdjacentHTML('beforeend',`<div class="assistant-message ${role}">${body}</div>`);$('assistant-messages').scrollTop=$('assistant-messages').scrollHeight}
function renderAssistantAction(action,index){const labels={draft_dsql_query:'DSQL query draft',draft_dynamodb_scan:'DynamoDB scan draft',draft_dynamodb_query:'DynamoDB query draft'},preview=action.input.sql||JSON.stringify(action.input,null,2);$('assistant-messages').insertAdjacentHTML('beforeend',`<div class="assistant-action"><b>${esc(labels[action.name]||action.name)}</b><pre>${esc(preview)}</pre><button data-assistant-action="${index}">Apply draft</button></div>`)}
function consolidateAssistantActions(actions,question=''){const scans=actions.filter(action=>action.name==='draft_dynamodb_scan');if(scans.length<2)return actions;const filters=scans.flatMap(action=>Array.isArray(action.input?.filters)?action.input.filters:action.input?.filterName?[{name:action.input.filterName,operator:action.input.filterOperator||'eq',value:action.input.filterValue,type:action.input.filterType}]:[]),first=scans[0].input||{},merged={name:'draft_dynamodb_scan',input:{filters,filterLogic:/\bor\b/i.test(question)?'OR':(first.filterLogic||'AND'),limit:first.limit||250,explanation:first.explanation||`Combined ${filters.length} filters into one scan`}},result=[],inserted=false;for(const action of actions){if(action.name==='draft_dynamodb_scan'){if(!inserted){result.push(merged);inserted=true}}else result.push(action)}return result}
function setValue(id,value){const element=$(id);if(element&&value!==undefined&&value!==null)element.value=typeof value==='object'?JSON.stringify(value,null,2):String(value)}
function activateDynamoOperation(operation){document.querySelectorAll('.operation-tabs button,.operation').forEach(element=>element.classList.remove('active'));document.querySelector(`.operation-tabs [data-operation="${operation}"]`)?.classList.add('active');$(`op-${operation}`)?.classList.add('active')}
function compileScanDraft(input){if(!Array.isArray(input.filters)||!input.filters.length)return input;const names={},values={},expressions=[],operators={eq:'=',ne:'<>',gt:'>',gte:'>=',lt:'<',lte:'<='};for(const [index,filter] of input.filters.slice(0,25).entries()){if(!filter?.name||!filter.operator)continue;const nameToken=`#f${index}`,valueToken=`:f${index}`;names[nameToken]=filter.name;if(!['exists','not_exists'].includes(filter.operator))values[valueToken]=filter.value;const expression=filter.operator==='contains'?`contains(${nameToken}, ${valueToken})`:filter.operator==='begins'?`begins_with(${nameToken}, ${valueToken})`:filter.operator==='exists'?`attribute_exists(${nameToken})`:filter.operator==='not_exists'?`attribute_not_exists(${nameToken})`:`${nameToken} ${operators[filter.operator]||'='} ${valueToken}`;expressions.push(`(${expression})`)}if(!expressions.length)return input;const first=input.filters[0],logic=String(input.filterLogic||'AND').toUpperCase()==='OR'?'OR':'AND';return{...input,filterName:first.name,filterOperator:first.operator,filterValue:first.value,filterType:first.type,filterExpression:expressions.join(` ${logic} `),expressionNames:names,expressionValues:values}}
function scanDraftFilter(input){if(input.filterName)return{name:input.filterName,operator:input.filterOperator||'eq',value:input.filterValue,type:input.filterType};const expression=String(input.filterExpression||'').trim(),names=input.expressionNames||{},values=input.expressionValues||{};if(!expression)return{};let match=expression.match(/(contains|begins_with)\s*\(\s*([^,]+)\s*,\s*([^\)]+)\s*\)/i),operator;if(match)operator=match[1].toLowerCase()==='begins_with'?'begins':'contains';else{match=expression.match(/(attribute_exists|attribute_not_exists)\s*\(\s*([^\)]+)\s*\)/i);if(match)operator=match[1].toLowerCase()==='attribute_exists'?'exists':'not_exists';else{match=expression.match(/(\S+)\s*(=|<>|>=|<=|>|<)\s*(\S+)/);operator=match&&({'=':'eq','<>':'ne','>':'gt','>=':'gte','<':'lt','<=':'lte'})[match[2]]}}if(!match)return{};const attributeToken=(operator==='contains'||operator==='begins')?match[2]:match[1],valueToken=(operator==='contains'||operator==='begins')?match[3]:match[3],name=names[attributeToken.trim()]||attributeToken.trim().replace(/^#/,''),literal=valueToken?.trim().match(/^['"](.*)['"]$/)?.[1],value=['exists','not_exists'].includes(operator)?undefined:(values[valueToken?.trim()]??literal),type=input.filterType||(typeof value==='number'?'number':typeof value==='boolean'?'boolean':'string');return{name,operator,value,type}}
function setAiScanExpression(input){const expression=String(input.filterExpression||'').trim(),field=$('scan-filter');field.dataset.aiDraft=expression?'1':'0';field.value=expression;setValue('scan-names',input.expressionNames||{});setValue('scan-values',input.expressionValues||{});let note=$('scan-ai-expression');if(expression){if(!note){$('run-scan').insertAdjacentHTML('beforebegin','<div id="scan-ai-expression" class="schema-strip"></div>');note=$('scan-ai-expression')}note.innerHTML=`<b>AI compound filter</b><code>${esc(expression)}</code>`}else note?.remove()}
function clearAiScanExpression(event){if(event&&!event.isTrusted)return;const field=$('scan-filter');if(field.dataset.aiDraft!=='1')return;field.dataset.aiDraft='0';field.value='';setValue('scan-names',{});setValue('scan-values',{});$('scan-ai-expression')?.remove()}
function syncScanFilterRow(row){const noValue=['exists','not_exists'].includes(row.querySelector('[data-filter-field="operator"]').value);row.querySelector('[data-filter-field="type"]').classList.toggle('hidden',noValue);row.querySelector('[data-filter-field="value"]').classList.toggle('hidden',noValue)}
function syncScanFilterRows(){const rows=[...document.querySelectorAll('.scan-filter-row')];$('scan-filter-logic').closest('label').classList.toggle('hidden',rows.length<2);rows.forEach(syncScanFilterRow)}
function addScanFilter(filter={}){const index=document.querySelectorAll('.scan-filter-row').length;$('scan-filter-rows').insertAdjacentHTML('beforeend',scanFilterRow(filter,index));const row=$('scan-filter-rows').lastElementChild;row.querySelector('[data-filter-field="operator"]').value=filter.operator||filter.filterOperator||'eq';row.querySelector('[data-filter-field="type"]').value=filter.type||filter.filterType||'string';clearAiScanExpression();syncScanFilterRows();row.querySelector('[data-filter-field="name"]').focus()}
function renderScanFilters(filters=[],logic='AND'){const usable=filters.length?filters:[{}];$('scan-filter-rows').innerHTML=usable.map((filter,index)=>scanFilterRow(filter,index)).join('');for(const [index,row] of [...document.querySelectorAll('.scan-filter-row')].entries()){row.querySelector('[data-filter-field="operator"]').value=usable[index].operator||usable[index].filterOperator||'eq';row.querySelector('[data-filter-field="type"]').value=usable[index].type||usable[index].filterType||'string'}$('scan-filter-logic').value=String(logic).toUpperCase()==='OR'?'OR':'AND';syncScanFilterRows()}
function clearScanFilter(){renderScanFilters();const field=$('scan-filter');field.dataset.aiDraft='0';field.value='';setValue('scan-names',{});setValue('scan-values',{});$('scan-ai-expression')?.remove();$('scan-filter-name').closest('details').open=false;toast('Scan filters cleared')}
function clearQueryFilter(){setValue('query-filter-name','');setValue('query-filter-operator','eq');setValue('query-filter-type','string');setValue('query-filter-value','');$('query-filter-operator').dispatchEvent(new Event('change'));$('query-filter-name').closest('details').open=false;toast('Query result filter cleared')}
async function applyAssistantAction(action){if(!action?.name)return toast('This AI draft is missing its operation type');const input=action.input||{};if(action.name==='draft_dsql_query'){if(!input.sql)return toast('The DSQL draft did not contain SQL');navigate('dsql');setValue('dsql-sql',input.sql);$('assistant-panel').classList.remove('open');$('dsql-sql').focus();toast('DSQL draft applied — review it before running');return}if(action.name==='draft_dynamodb_scan'){const draft=compileScanDraft(input),filters=Array.isArray(draft.filters)?draft.filters:[scanDraftFilter(draft)].filter(filter=>filter.name);navigate('dynamodb');activateDynamoOperation('scan');renderScanFilters(filters,draft.filterLogic);setAiScanExpression(draft);setValue('scan-limit',draft.limit??50);if(filters.length)$('scan-filter-name').closest('details').open=true;$('assistant-panel').classList.remove('open');$('scan-filter-name').focus();toast(filters.length?`DynamoDB scan draft applied with ${filters.length} filter${filters.length===1?'':'s'} — review it before running`:'Scan limit applied, but the model did not provide a usable filter');return}if(action.name==='draft_dynamodb_query'){navigate('dynamodb');activateDynamoOperation('query');if(!tableDescription&&$('table-select').value)await loadTableDescription();if(input.partitionKeyValue===undefined||input.partitionKeyValue===null)return toast('The DynamoDB query draft is missing its partition-key value');const requestedIndex=input.index||'',available=[...$('query-index').options].some(option=>option.value===requestedIndex);$('query-index').value=available?requestedIndex:'';applyQueryTemplate();setValue('query-limit',input.limit??50);setValue('query-pk-value',input.partitionKeyValue);setValue('query-sk-operator',input.sortKeyOperator??'');syncSortInputs();setValue('query-sk-value',input.sortKeyValue);setValue('query-sk-value-2',input.sortKeyValue2);setValue('query-filter-name',input.filterName??'');setValue('query-filter-operator',input.filterOperator??'eq');setValue('query-filter-value',input.filterValue);setValue('query-filter-type',input.filterType??'string');$('query-filter-operator').dispatchEvent(new Event('change'));if(input.filterName)$('query-filter-name').closest('details').open=true;$('assistant-panel').classList.remove('open');$('query-pk-value').focus();toast('DynamoDB query draft applied — review it before running');return}toast(`Unsupported AI draft: ${action.name}`)}
async function askAssistant(event){event.preventDefault();const question=$('assistant-question').value.trim(),modelId=$('assistant-model').value;if(!question)return;addAssistantMessage('user',question);$('assistant-question').value='';$('assistant-send').classList.add('loading');$('assistant-send').disabled=true;try{const result=await post('/api/bedrock/converse',{modelId,question,context:assistantContext(),history:assistantHistory,attachment:assistantAttachment()}),actions=consolidateAssistantActions(result.actions||[],question);addAssistantMessage('assistant',result.text);assistantHistory.push({role:'user',text:question},{role:'assistant',text:result.text});assistantHistory=assistantHistory.slice(-8);for(const action of actions){assistantActions.push(action);renderAssistantAction(action,assistantActions.length-1)}}catch(error){addAssistantMessage('assistant',`Bedrock error: ${error.message}`)}finally{$('assistant-send').classList.remove('loading');$('assistant-send').disabled=false}}
async function initAssistant(){try{const data=await api('/api/bedrock/models'),saved=localStorage.getItem('stackeye.bedrock.model');$('assistant-model').innerHTML=data.models.map(model=>`<option value="${esc(model.id)}">${esc(model.name)}${model.multimodal?' · PDF/images':''}</option>`).join('');if(saved&&data.models.some(model=>model.id===saved))$('assistant-model').value=saved}catch(error){$('assistant-model').innerHTML='<option value="">Bedrock unavailable</option>';$('assistant-model').title=error.message}refreshAssistantContext()}
$('assistant-open').onclick=()=>{$('assistant-panel').classList.add('open');refreshAssistantContext();$('assistant-question').focus()};$('assistant-close').onclick=()=>$('assistant-panel').classList.remove('open');$('assistant-form').onsubmit=askAssistant;$('assistant-model').onchange=()=>localStorage.setItem('stackeye.bedrock.model',$('assistant-model').value);$('assistant-messages').onclick=event=>{const button=event.target.closest('[data-assistant-action]');if(button)applyAssistantAction(assistantActions[Number(button.dataset.assistantAction)])};document.querySelector('nav').addEventListener('click',()=>setTimeout(refreshAssistantContext));initAssistant();
